1	import type { Data, Element as HastElement } from "hast";
2	
3	export interface TagNode {
4	  type: "tagNode";
5	  value: string;
6	  data: TagNodeData;
7	}
8	
9	export interface MentionNode {
10	  type: "mentionNode";
11	  value: string;
12	  data: MentionNodeData;
13	}
14	
15	export interface TagNodeData {
16	  hName: "span";
17	  hProperties: TagNodeProperties;
18	  hChildren: Array<{ type: "text"; value: string }>;
19	}
20	
21	export interface MentionNodeData {
22	  hName: "span";
23	  hProperties: MentionNodeProperties;
24	  hChildren: Array<{ type: "text"; value: string }>;
25	}
26	
27	export interface TagNodeProperties {
28	  className: string;
29	  "data-tag": string;
30	}
31	
32	export interface MentionNodeProperties {
33	  className: string;
34	  "data-mention": string;
35	}
36	
37	export interface ExtendedData extends Data {
38	  mdastType?: string;
39	}
40	
41	export function hasExtendedData(node: unknown): node is { data: ExtendedData } {
42	  return typeof node === "object" && node !== null && "data" in node && typeof (node as { data: unknown }).data === "object";
43	}
44	
45	export function isTagElement(node: HastElement): boolean {
46	  if (hasExtendedData(node) && node.data.mdastType === "tagNode") {
47	    return true;
48	  }
49	
50	  const dataTag = node.properties?.["data-tag"];
51	  if (typeof dataTag === "string" && dataTag !== "") {
52	    return true;
53	  }
54	
55	  const className = node.properties?.className;
56	  if (Array.isArray(className) && className.includes("tag")) {
57	    return true;
58	  }
59	  if (typeof className === "string" && className.split(/\s+/).includes("tag")) {
60	    return true;
61	  }
62	
63	  return false;
64	}
65	
66	export function isMentionElement(node: HastElement): boolean {
67	  if (hasExtendedData(node) && node.data.mdastType === "mentionNode") {
68	    return true;
69	  }
70	
71	  const dataMention = node.properties?.["data-mention"];
72	  if (typeof dataMention === "string" && dataMention !== "") {
73	    return true;
74	  }
75	
76	  const className = node.properties?.className;
77	  if (Array.isArray(className) && className.includes("mention")) {
78	    return true;
79	  }
80	  if (typeof className === "string" && className.split(/\s+/).includes("mention")) {
81	    return true;
82	  }
83	
84	  return false;
85	}
86	
87	export function isTaskListItemElement(node: HastElement): boolean {
88	  const type = node.properties?.type;
89	  return typeof type === "string" && type === "checkbox";
90	}
